const getAwardsPaginated = `-- name: GetAwardsPaginated :many
SELECT id, status, reason, methodist, teacher, total_points, type, variant, criteria, bonus_criteria, category_id, field_values, created_at, updated_at FROM awards
WHERE
    (
        $1 = ''
        OR (
            $1 ~* '^[0-9a-f-]{36}$'
            AND id = $1::uuid
        )
        OR status::text ILIKE '%' || $1 || '%'
        OR COALESCE(reason::text, '') ILIKE '%' || $1 || '%'
    )
    AND
    (
        $2::uuid IS NULL
        OR teacher = $2::uuid
    )
    AND (
        $3::uuid IS NULL
        OR methodist = $3::uuid
    )
    AND (
        $4::uuid[] IS NULL
        OR category_id = ANY($4::uuid[])
    )
    AND (
        $5::text[] IS NULL
        OR status = ANY($5::text[]::awards_status[])
    )
ORDER BY
    CASE WHEN LOWER($6::text) = 'asc' THEN status::text END ASC,
    CASE WHEN LOWER($6::text) = 'asc' THEN created_at END ASC,
    CASE WHEN LOWER($6::text) = 'desc' THEN status::text END DESC,
    CASE WHEN LOWER($6::text) = 'desc' THEN created_at END DESC,
    created_at DESC
LIMIT $8 OFFSET $7
`

